void save(std::ostream &out, const std::vector<int> &values) {
    out << "EV1 " << values.size();
    for (int x : values) {
        out << ' ' << x;
    }
    out << '\n';
}
int main() {
    std::vector<int> model{99};
    if (!load(std::cin, model)) {
        std::cout << "rejected " << model[0] << '\n';
        return 0;
    }
    std::ostringstream bytes;
    save(bytes, model);
    std::istringstream input(bytes.str());
    std::vector<int> copy;
    if (!load(input, copy) || copy != model) {
        return 1;
    }
    std::cout << bytes.str();
}
